// Função anti-mock
function ehMock(num) {
  if (!num) return true;
  const dig = num.replace(/\D/g, '');
  if (dig.length < 10) return true;
  if (['5532984587255', '553284587255', '553285066687', '5532988273367', '553288273367'].includes(dig)) return false;
  const mocks = ['99998888', '99997777', '988881111', '123456', '000000'];
  return mocks.some(m => dig.includes(m));
}

for (const a of alunos) {
  if (!a.telefone || ehMock(a.telefone)) continue;
  const rawTel = a.telefone.replace(/\D/g, '');
  const nome = (a.nome || a.nome_aluno || a.nome_cliente || 'Guerreiro(a)').trim().split(' ')[0];
  const obj = (a.objetivo || '').toLowerCase();
  const restricoes = (a.restricoes || a.restricoes_saude || '').toLowerCase();

  // REGRA SUPREMA: DIRETOR E FUNDADOR EVANDRO GALLINA
  const isEvandro = ['553284587255', '5532984587255'].includes(rawTel) ||
                    rawTel.endsWith('84587255') ||
                    (a.nome && a.nome.toLowerCase().includes('evandro'));
  if (isEvandro) {
    continue;
  }

  const compNome = a.competicao_alvo || (obj.includes('compet') || obj.includes('campeonato') || obj.includes('corrida') || obj.includes('maratona') ? 'sua competição' : null);
