  const localPendente = !a.local_treino || String(a.local_treino).includes('Pendente');
  const restricoesPendente = !a.restricoes || String(a.restricoes).includes('Pendente');
  const dadosCompletos = a.dados_completos === true || (lgpdAutorizado && !pesoPendente && !localPendente);

  const isTeste = $input.first().json.query && $input.first().json.query.teste;

  // =========================================================================
  // 1. PRIORIDADE MÁXIMA: COBRANÇA DIVERTIDA DE DADOS FALTANTES (SE NÃO AUTORIZADO)
  // =========================================================================
  if (!dadosCompletos && isTeste !== 'atleta') {
    if (lgpdPendente) {
      disparos.push({
        telefone: rawTel,
        remote_jid: a.remote_jid,
        tipo: 'cobranca_lgpd_divertida',
        eh_upsell: false,
        texto: `Fala, ${nome}! 🦁 Marcão Personal na área!\n\nSeu planejamento VIP tá no forno e louco pra sair do papel! Mas como personal responsável (e pra cumprirmos a lei da LGPD e a sua segurança), só preciso de uma palavrinha mágica de confirmação:\n\nMe manda um 'CONCORDO' aqui embaixo que libero sua rotina de treino e suas metas de nutrição na mesma hora! Bora pra cima! 💪👊`
      });
      continue;
    } else if (pesoPendente) {
      disparos.push({
        telefone: rawTel,
        remote_jid: a.remote_jid,
        tipo: 'cobranca_peso_divertida',
        eh_upsell: false,
        texto: `Fala, ${nome}! 🦁 Marcão passando com todo o carinho e energia pra saber: já tirou a poeira da nossa Balança Inteligente hoje? Hahaha! 😄⚖️\n\nSobe nela rapidinho em jejum e me manda uma foto do visor ou digita seu peso aqui! A balança é o nosso mapa da mina pra calibrar seu shape e sua evolução! Tamo junto! 👊`
      });
      continue;
    } else if (localPendente) {
      disparos.push({
        telefone: rawTel,
        remote_jid: a.remote_jid,
        tipo: 'cobranca_local_divertida',
        eh_upsell: false,
        texto: `E aí, ${nome}! 👊 Marcão passando no capricho! Tô aqui montando sua estratégia, mas o treinador precisa de 2 respostas rápidas pra deixar seu treino sob medida:\n\n1️⃣ Você vai treinar na academia ou no conforto de casa com coisas simples (tipo cadeira e vassoura)?\n2️⃣ Qual sua idade e altura aproximadas?\n\nMe conta aqui no seu tempo pra gente deixar sua rotina 100% personalizada e elegante! Tamo junto! 🔥`
      });
      continue;
    } else if (restricoesPendente) {
      disparos.push({
        telefone: rawTel,
        remote_jid: a.remote_jid,
        tipo: 'cobranca_restricoes_divertida',
        eh_upsell: false,
        texto: `Opa, ${nome}! 🦁 Treinador Marcão na área! Uma pergunta fundamental pra sua segurança articular:\n\nVocê tem alguma dorzinha ou lesão antiga no joelho, coluna ou ombro que eu precise saber pra blindar seus treinos? Me avisa aqui! Tamo junto! 💪`
      });
      continue;
    }
  }

