    disparos.push({
      telefone: rawTel,
      remote_jid: a.remote_jid,
      tipo: 'surpresa_terca_playlist',
      eh_upsell: false,
      texto: `E aí, ${nome}! 👊 Marcão passando no meio da sua tarde pra garantir que o treino de hoje vai ser pesado!\n\nBota um Gym Phonk no fone ou aquele som dos anos 90 pra dar o pico de adrenalina! O Dr. Brad Schoenfeld comprovou que 10 a 20 séries semanais com carga alta é a chave do tônus muscular!\n\nBora pra cima! Depois me conta como foi o treino!`
    });
  } else if (diaSemana === 3 || isTeste === 'quarta') {
    // QUARTA 18:00 - Checagem Nutricional & Fotos de Evolução
    disparos.push({
      telefone: rawTel,
      remote_jid: a.remote_jid,
      tipo: 'checkin_quarta',
      eh_upsell: false,
      texto: `Fala, ${nome}! Metade da semana vencida! Como tá a pegada dos treinos?\n\nPassando pra ver se o treino de hoje já tá pago! Me manda uma foto do seu prato de jantar pra eu calibrar seus macros! E se puder, apoia o celular de frente pra janela ou pede pra alguém tirar uma foto de corpo inteiro pra gente comparar a evolução do shape! Tamo junto, guerreiro(a)!`
    });
  } else if (diaSemana === 4 || isTeste === 'quinta') {
    // QUINTA 22:30 - Sono Anabólico
    disparos.push({
      telefone: rawTel,
      remote_jid: a.remote_jid,
      tipo: 'surpresa_quinta_sono',
      eh_upsell: false,
      texto: `Opa, ${nome}! 🦁 Marcão passando pra te mandar pra cama agora!\n\nEstudo de Harvard comprovou que mais de 70% do pico de GH e recuperação muscular acontecem no sono profundo!\n\nLarga o celular, bebe um copo d'água e descansa a carcaça pra amanhã acordar 100%! Boa noite!`
    });
  } else if (diaSemana === 5 || isTeste === 'sexta') {
    // SEXTA 18:30 - Fechamento Semanal
    disparos.push({
      telefone: rawTel,
      remote_jid: a.remote_jid,
      tipo: 'checkin_sexta',
      eh_upsell: false,
      texto: `Fala, ${nome}! 🦁 Sextou com a sensação de dever cumprido!\n\nFechamos a meta semanal de treinos com chave de ouro! Agora no fim de semana, descanso com moderação e nada de jogar fora o esforço dos últimos 5 dias, combinado?\n\nSegura a hidratação e excelente descanso!`
